--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: actualizar_cuenta_por_cobrar(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.actualizar_cuenta_por_cobrar() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_total    NUMERIC;
  v_pagado   NUMERIC;
BEGIN
  SELECT monto_total INTO v_total
  FROM cuentas_por_cobrar WHERE id = NEW.cuenta_id;

  SELECT COALESCE(SUM(monto), 0) INTO v_pagado
  FROM pagos_cuentas WHERE cuenta_id = NEW.cuenta_id;

  UPDATE cuentas_por_cobrar SET
    monto_pagado   = v_pagado,
    monto_pendiente = GREATEST(v_total - v_pagado, 0),
    estado = CASE
      WHEN v_pagado >= v_total THEN 'pagada'
      WHEN v_pagado > 0        THEN 'parcial'
      ELSE 'pendiente'
    END,
    updated_at = NOW()
  WHERE id = NEW.cuenta_id;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.actualizar_cuenta_por_cobrar() OWNER TO postgres;

--
-- Name: anular_orden_restaurante(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.anular_orden_restaurante(p_payment_id uuid, p_motivo_categoria text, p_motivo_detalle text, p_usuario_id uuid, p_negocio_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_pago           RECORD;
  v_ncf_b04        TEXT    := NULL;
  v_tiene_fiscal   BOOLEAN := FALSE;
BEGIN
  -- Obtener pago
  SELECT rop.*, ro.negocio_id AS orden_negocio_id
    INTO v_pago
    FROM restaurant_order_payments rop
    JOIN restaurant_orders ro ON ro.id = rop.order_id
   WHERE rop.id = p_payment_id
     AND ro.negocio_id = p_negocio_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pago % no encontrado', p_payment_id;
  END IF;

  IF v_pago.anulado = TRUE THEN
    RAISE EXCEPTION 'El pago % ya está anulado', p_payment_id;
  END IF;

  -- Intentar generar B04 si el pago tiene NCF
  IF v_pago.ncf IS NOT NULL AND v_pago.ncf <> '' THEN
    BEGIN
      v_ncf_b04 := obtener_siguiente_ncf('B04', p_negocio_id);
      v_tiene_fiscal := TRUE;
    EXCEPTION WHEN OTHERS THEN
      v_ncf_b04 := NULL;
      v_tiene_fiscal := FALSE;
    END;
  END IF;

  -- Marcar pago como anulado
  UPDATE restaurant_order_payments
     SET anulado        = TRUE,
         ncf_referencia = v_ncf_b04
   WHERE id = p_payment_id;

  -- Reabrir la orden (estado → abierta)
  UPDATE restaurant_orders
     SET estado     = 'abierta',
         hora_cierre = NULL
   WHERE id = v_pago.order_id;

  -- Registrar en anulaciones
  INSERT INTO anulaciones (
    negocio_id, order_payment_id,
    ncf_original, tipo_ncf_original,
    ncf_nota_credito, tiene_nota_credito,
    motivo_categoria, motivo_detalle,
    usuario_id
  ) VALUES (
    p_negocio_id, p_payment_id,
    v_pago.ncf, v_pago.tipo_ncf,
    v_ncf_b04, v_tiene_fiscal,
    p_motivo_categoria, p_motivo_detalle,
    p_usuario_id
  );

  RETURN json_build_object(
    'ok',       TRUE,
    'ncf_b04',  v_ncf_b04
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'anular_orden_restaurante falló: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
END;
$$;


ALTER FUNCTION public.anular_orden_restaurante(p_payment_id uuid, p_motivo_categoria text, p_motivo_detalle text, p_usuario_id uuid, p_negocio_id uuid) OWNER TO postgres;

--
-- Name: anular_venta_completa(bigint, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.anular_venta_completa(p_venta_id bigint, p_motivo_categoria text, p_motivo_detalle text, p_usuario_id uuid, p_negocio_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_venta          RECORD;
  v_ncf_b04        TEXT   := NULL;
  v_tiene_fiscal   BOOLEAN := FALSE;
BEGIN
  -- Obtener venta
  SELECT * INTO v_venta
    FROM ventas
   WHERE id = p_venta_id
     AND negocio_id = p_negocio_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Venta % no encontrada', p_venta_id;
  END IF;

  IF v_venta.estado = 'anulada' THEN
    RAISE EXCEPTION 'La venta % ya está anulada', p_venta_id;
  END IF;

  -- Intentar generar B04 si la venta tiene NCF
  IF v_venta.ncf IS NOT NULL AND v_venta.ncf <> '' THEN
    BEGIN
      v_ncf_b04 := obtener_siguiente_ncf('B04', p_negocio_id);
      v_tiene_fiscal := TRUE;
    EXCEPTION WHEN OTHERS THEN
      -- Sin secuencia B04 configurada: anular igualmente sin nota de crédito
      v_ncf_b04 := NULL;
      v_tiene_fiscal := FALSE;
    END;
  END IF;

  -- Marcar venta como anulada
  UPDATE ventas
     SET estado         = 'anulada',
         ncf_referencia = v_ncf_b04,
         updated_at     = NOW()
   WHERE id = p_venta_id;

  -- Restaurar stock
  UPDATE productos p
     SET stock_actual = COALESCE(p.stock_actual, 0) + vd.cantidad
    FROM ventas_detalle vd
   WHERE vd.venta_id   = p_venta_id
     AND vd.producto_id = p.id;

  -- Registrar en anulaciones
  INSERT INTO anulaciones (
    negocio_id, venta_id,
    ncf_original, tipo_ncf_original,
    ncf_nota_credito, tiene_nota_credito,
    motivo_categoria, motivo_detalle,
    usuario_id
  ) VALUES (
    p_negocio_id, p_venta_id,
    v_venta.ncf, v_venta.tipo_ncf,
    v_ncf_b04, v_tiene_fiscal,
    p_motivo_categoria, p_motivo_detalle,
    p_usuario_id
  );

  RETURN json_build_object(
    'ok',       TRUE,
    'ncf_b04',  v_ncf_b04
  );

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'anular_venta_completa falló: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
END;
$$;


ALTER FUNCTION public.anular_venta_completa(p_venta_id bigint, p_motivo_categoria text, p_motivo_detalle text, p_usuario_id uuid, p_negocio_id uuid) OWNER TO postgres;

--
-- Name: asignar_numero_pedido_dia(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.asignar_numero_pedido_dia() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_numero SMALLINT;
BEGIN
  IF NEW.tipo_orden IN ('barra', 'llevar', 'delivery') THEN
    SELECT COALESCE(MAX(numero_pedido_dia), 0) + 1
      INTO v_numero
      FROM restaurant_orders
     WHERE negocio_id = NEW.negocio_id
       AND tipo_orden IN ('barra', 'llevar', 'delivery')
       AND (created_at AT TIME ZONE 'America/Santo_Domingo')::date
             = (NOW() AT TIME ZONE 'America/Santo_Domingo')::date;
    NEW.numero_pedido_dia := v_numero;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.asignar_numero_pedido_dia() OWNER TO postgres;

--
-- Name: crear_venta_completa(jsonb, integer, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.crear_venta_completa(p_venta jsonb, p_usuario_id integer, p_negocio_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_numero_venta   TEXT;
  v_venta_id       INT;
  v_detalle        JSONB;
  v_producto_id    INT;
  v_cantidad       NUMERIC;
  v_cliente_id     INT;
  v_total          NUMERIC;
  v_tipo_venta     TEXT;
BEGIN
  v_numero_venta := generar_numero_factura();

  INSERT INTO ventas (
    numero_venta, cliente_id, caja_id, subtotal, descuento,
    impuestos, total, metodo_pago, tipo_venta, estado, notas,
    ncf, tipo_ncf, rnc_cliente, nombre_cliente_fiscal,
    mesa_id, pedido_id, negocio_id, created_at
  )
  VALUES (
    v_numero_venta,
    NULLIF((p_venta->>'cliente_id'), '')::INT,
    NULLIF((p_venta->>'caja_id'), '')::INT,
    (p_venta->>'subtotal')::NUMERIC,
    COALESCE((p_venta->>'descuento')::NUMERIC, 0),
    COALESCE((p_venta->>'impuesto')::NUMERIC, 0),
    (p_venta->>'total')::NUMERIC,
    (p_venta->>'metodo_pago'),
    COALESCE(p_venta->>'tipo_venta', 'contado'),
    'completada',
    p_venta->>'notas',
    p_venta->>'ncf',
    p_venta->>'tipo_ncf',
    p_venta->>'rnc_cliente',
    p_venta->>'nombre_cliente_fiscal',
    NULLIF((p_venta->>'mesa_id'), '')::INT,
    NULLIF((p_venta->>'pedido_id'), '')::INT,
    p_negocio_id,
    NOW()
  )
  RETURNING id INTO v_venta_id;

  FOR v_detalle IN SELECT * FROM jsonb_array_elements(p_venta->'detalles')
  LOOP
    v_producto_id := (v_detalle->>'producto_id')::INT;
    v_cantidad    := (v_detalle->>'cantidad')::NUMERIC;

    INSERT INTO ventas_detalle (
      venta_id, producto_id, producto_nombre, cantidad,
      precio_unitario, descuento, subtotal, notas
    )
    VALUES (
      v_venta_id,
      v_producto_id,
      v_detalle->>'producto_nombre',
      v_cantidad,
      (v_detalle->>'precio_unitario')::NUMERIC,
      COALESCE((v_detalle->>'descuento')::NUMERIC, 0),
      (v_detalle->>'subtotal')::NUMERIC,
      v_detalle->>'notas'
    );

    UPDATE productos
       SET stock_actual = COALESCE(stock_actual, 0) - v_cantidad
     WHERE id = v_producto_id;
  END LOOP;

  v_tipo_venta := COALESCE(p_venta->>'tipo_venta', 'contado');
  v_cliente_id := NULLIF((p_venta->>'cliente_id'), '')::INT;

  IF v_tipo_venta = 'credito' AND v_cliente_id IS NOT NULL THEN
    v_total := (p_venta->>'total')::NUMERIC;
    UPDATE clientes
       SET balance_pendiente = COALESCE(balance_pendiente, 0) + v_total
     WHERE id = v_cliente_id;
  END IF;

  RETURN json_build_object('id', v_venta_id, 'numero_venta', v_numero_venta);

EXCEPTION WHEN OTHERS THEN
  RAISE EXCEPTION 'crear_venta_completa falló: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
END;
$$;


ALTER FUNCTION public.crear_venta_completa(p_venta jsonb, p_usuario_id integer, p_negocio_id uuid) OWNER TO postgres;

--
-- Name: generar_numero_factura(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generar_numero_factura() RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_fecha     TEXT;
  v_contador  INT;
  v_numero    TEXT;
BEGIN
  v_fecha := TO_CHAR(NOW(), 'YYYYMMDD');

  -- Contar ventas del día para obtener correlativo
  SELECT COUNT(*) + 1
    INTO v_contador
    FROM ventas
   WHERE DATE(created_at) = CURRENT_DATE;

  v_numero := 'FAC-' || v_fecha || '-' || LPAD(v_contador::TEXT, 4, '0');
  RETURN v_numero;
END;
$$;


ALTER FUNCTION public.generar_numero_factura() OWNER TO postgres;

--
-- Name: get_impresoras_negocio(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_impresoras_negocio(p_negocio_id uuid) RETURNS TABLE(id uuid, nombre text, descripcion text, ip text, puerto integer, tipo text, caracteres_por_linea integer, corte_automatico boolean, copies smallint, activa boolean)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    id, nombre, descripcion, ip, puerto,
    tipo, caracteres_por_linea, corte_automatico, copies, activa
  FROM restaurant_printers
  WHERE negocio_id = p_negocio_id
    AND activa = true
  ORDER BY tipo, nombre;
$$;


ALTER FUNCTION public.get_impresoras_negocio(p_negocio_id uuid) OWNER TO postgres;

--
-- Name: get_mesas_resumen(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_mesas_resumen(p_negocio_id uuid) RETURNS TABLE(mesa_id uuid, numero_mesa integer, nombre_mesa text, zona_id uuid, zona_nombre text, capacidad integer, estado_mesa text, orden_id uuid, estado_orden text, total_orden numeric, hora_apertura timestamp with time zone, items_count bigint, tiempo_minutos integer)
    LANGUAGE plpgsql
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    rt.id,
    rt.numero_mesa,
    rt.nombre_mesa,
    rt.zona_id,
    rz.nombre,
    rt.capacidad,
    rt.estado,
    ro.id,
    ro.estado,
    ro.total,
    ro.hora_apertura,
    COUNT(roi.id),
    EXTRACT(EPOCH FROM (NOW() - ro.hora_apertura))::INT / 60
  FROM restaurant_tables rt
  JOIN restaurant_zones rz ON rz.id = rt.zona_id
  LEFT JOIN restaurant_orders ro
    ON ro.table_id = rt.id
    AND ro.estado NOT IN ('cerrada', 'cancelada')
  LEFT JOIN restaurant_order_items roi
    ON roi.order_id = ro.id
    AND roi.estado != 'cancelado'
  WHERE rt.negocio_id = p_negocio_id
    AND rt.activa = true
  GROUP BY rt.id, rt.numero_mesa, rt.nombre_mesa, rt.zona_id,
           rz.nombre, rt.capacidad, rt.estado,
           ro.id, ro.estado, ro.total, ro.hora_apertura
  ORDER BY rz.nombre, rt.numero_mesa;
END;
$$;


ALTER FUNCTION public.get_mesas_resumen(p_negocio_id uuid) OWNER TO postgres;

--
-- Name: get_ruteo_orden(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_ruteo_orden(p_order_id uuid) RETURNS TABLE(printer_id uuid, printer_nombre text, printer_ip text, printer_puerto integer, printer_tipo text, printer_tipo_conexion text, printer_puerto_usb text, printer_chars integer, printer_corte boolean, printer_copies integer, item_id uuid, menu_item_nombre text, cantidad integer, modificadores jsonb, notas_especiales text, comensal_asignado integer)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    rp.id                   AS printer_id,
    rp.nombre               AS printer_nombre,
    rp.ip                   AS printer_ip,
    rp.puerto               AS printer_puerto,
    rp.tipo                 AS printer_tipo,
    rp.tipo_conexion        AS printer_tipo_conexion,
    rp.puerto_usb           AS printer_puerto_usb,
    rp.caracteres_por_linea AS printer_chars,
    rp.corte_automatico     AS printer_corte,
    rp.copies               AS printer_copies,
    roi.id                  AS item_id,
    mi.nombre               AS menu_item_nombre,
    roi.cantidad,
    roi.modificadores::JSONB,
    roi.notas_especiales,
    roi.comensal_asignado
  FROM restaurant_order_items roi
  JOIN menu_items          mi  ON mi.id  = roi.menu_item_id
  JOIN menu_categories     mc  ON mc.id  = mi.categoria_id
  JOIN restaurant_printers rp  ON rp.id  = mc.printer_id
  WHERE roi.order_id = p_order_id
    AND roi.estado   = 'pendiente'
    AND mc.printer_id IS NOT NULL
  ORDER BY rp.tipo, mi.nombre;
$$;


ALTER FUNCTION public.get_ruteo_orden(p_order_id uuid) OWNER TO postgres;

--
-- Name: obtener_siguiente_ncf(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.obtener_siguiente_ncf(tipo_solicitado text, p_negocio_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_seq       RECORD;
  v_nuevo_num INT;
  v_ncf       TEXT;
BEGIN
  -- Bloquear la fila para evitar secuencias duplicadas bajo concurrencia
  SELECT *
    INTO v_seq
    FROM secuencias_ncf
   WHERE tipo_ncf    = UPPER(tipo_solicitado)
     AND negocio_id  = p_negocio_id
     AND activo      = TRUE
     AND (fecha_vencimiento IS NULL OR fecha_vencimiento >= CURRENT_DATE)
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'No hay secuencia NCF activa para tipo % en el negocio %',
      tipo_solicitado, p_negocio_id;
  END IF;

  v_nuevo_num := v_seq.numero_actual + 1;

  IF v_nuevo_num > v_seq.rango_final THEN
    RAISE EXCEPTION 'Secuencia NCF % agotada (rango_final = %)',
      tipo_solicitado, v_seq.rango_final;
  END IF;

  -- Actualizar secuencia
  UPDATE secuencias_ncf
     SET numero_actual        = v_nuevo_num,
         ultima_actualizacion = NOW()
   WHERE id = v_seq.id;

  -- Formato: prefijo (B01, B02…) + número 11 dígitos
  v_ncf := UPPER(v_seq.prefijo) || LPAD(v_nuevo_num::TEXT, 11, '0');
  RETURN v_ncf;
END;
$$;


ALTER FUNCTION public.obtener_siguiente_ncf(tipo_solicitado text, p_negocio_id uuid) OWNER TO postgres;

--
-- Name: recalcular_totales_orden(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalcular_totales_orden() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_negocio_id    UUID;
  v_tasa          NUMERIC;
  v_modo          VARCHAR(20);
  v_suma_items    NUMERIC;
  v_subtotal      NUMERIC;
  v_impuesto      NUMERIC;
  v_descuento     NUMERIC;
  v_total         NUMERIC;
BEGIN
  -- Obtener el negocio_id de la orden
  SELECT negocio_id INTO v_negocio_id
  FROM restaurant_orders
  WHERE id = COALESCE(NEW.order_id, OLD.order_id);

  -- Leer configuración fiscal del negocio
  SELECT
    COALESCE(tasa_itbis, 0),
    COALESCE(modo_impuesto, 'sin_impuesto')
  INTO v_tasa, v_modo
  FROM negocios
  WHERE id = v_negocio_id;

  -- Suma bruta de items activos (precio_unitario * cantidad)
  SELECT COALESCE(SUM(subtotal), 0) INTO v_suma_items
  FROM restaurant_order_items
  WHERE order_id = COALESCE(NEW.order_id, OLD.order_id)
    AND estado <> 'cancelado';

  -- Descuento de la orden (si existe)
  SELECT COALESCE(descuento, 0) INTO v_descuento
  FROM restaurant_orders
  WHERE id = COALESCE(NEW.order_id, OLD.order_id);

  -- Calcular subtotal e impuesto según modo
  CASE v_modo
    WHEN 'incluido' THEN
      -- El precio ya incluye ITBIS: extraer impuesto hacia atrás
      IF v_tasa > 0 THEN
        v_subtotal  := ROUND((v_suma_items - v_descuento) / (1 + v_tasa), 2);
        v_impuesto  := ROUND((v_suma_items - v_descuento) - v_subtotal, 2);
      ELSE
        v_subtotal  := v_suma_items - v_descuento;
        v_impuesto  := 0;
      END IF;

    WHEN 'encima' THEN
      -- ITBIS se suma por encima del precio base
      v_subtotal  := v_suma_items - v_descuento;
      v_impuesto  := ROUND(v_subtotal * v_tasa, 2);

    ELSE -- 'sin_impuesto'
      v_subtotal  := v_suma_items - v_descuento;
      v_impuesto  := 0;
  END CASE;

  v_total := v_subtotal + v_impuesto;

  -- Actualizar totales en la orden
  UPDATE restaurant_orders
  SET
    subtotal    = v_subtotal,
    impuesto    = v_impuesto,
    total       = v_total,
    updated_at  = NOW()
  WHERE id = COALESCE(NEW.order_id, OLD.order_id);

  RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.recalcular_totales_orden() OWNER TO postgres;

--
-- Name: registrar_movimiento_inventario(uuid, uuid, text, numeric, text, uuid, text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.registrar_movimiento_inventario(p_negocio_id uuid, p_inventory_item_id uuid, p_tipo text, p_cantidad numeric, p_razon text DEFAULT NULL::text, p_referencia_id uuid DEFAULT NULL::uuid, p_referencia_tipo text DEFAULT NULL::text, p_usuario_id bigint DEFAULT NULL::bigint) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cantidad_anterior  DECIMAL(10,3);
  v_cantidad_posterior DECIMAL(10,3);
  v_movement_id        UUID;
BEGIN
  SELECT cantidad_actual INTO v_cantidad_anterior
  FROM restaurant_inventory
  WHERE id = p_inventory_item_id AND negocio_id = p_negocio_id
  FOR UPDATE;

  IF v_cantidad_anterior IS NULL THEN
    RAISE EXCEPTION 'Ítem de inventario no encontrado: %', p_inventory_item_id;
  END IF;

  IF p_tipo IN ('entrada', 'ajuste') THEN
    v_cantidad_posterior := v_cantidad_anterior + ABS(p_cantidad);
  ELSIF p_tipo IN ('salida', 'merma', 'produccion') THEN
    v_cantidad_posterior := v_cantidad_anterior - ABS(p_cantidad);
    IF v_cantidad_posterior < 0 THEN
      RAISE EXCEPTION 'Stock insuficiente. Disponible: %, Solicitado: %',
        v_cantidad_anterior, ABS(p_cantidad);
    END IF;
  ELSE
    RAISE EXCEPTION 'Tipo de movimiento inválido: %', p_tipo;
  END IF;

  UPDATE restaurant_inventory
  SET cantidad_actual = v_cantidad_posterior, updated_at = NOW()
  WHERE id = p_inventory_item_id AND negocio_id = p_negocio_id;

  INSERT INTO restaurant_inventory_movements (
    negocio_id, inventory_item_id, tipo_movimiento,
    cantidad, cantidad_anterior, cantidad_posterior,
    razon, referencia_id, referencia_tipo, usuario_id
  ) VALUES (
    p_negocio_id, p_inventory_item_id, p_tipo,
    ABS(p_cantidad), v_cantidad_anterior, v_cantidad_posterior,
    p_razon, p_referencia_id, p_referencia_tipo, p_usuario_id
  ) RETURNING id INTO v_movement_id;

  RETURN v_movement_id;
END;
$$;


ALTER FUNCTION public.registrar_movimiento_inventario(p_negocio_id uuid, p_inventory_item_id uuid, p_tipo text, p_cantidad numeric, p_razon text, p_referencia_id uuid, p_referencia_tipo text, p_usuario_id bigint) OWNER TO postgres;

