--
-- Name: sincronizar_estado_mesa(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.sincronizar_estado_mesa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_ordenes_activas INT;
BEGIN
  IF TG_OP = 'INSERT' AND NEW.estado = 'abierta' THEN
    UPDATE restaurant_tables
    SET estado = 'ocupada', updated_at = NOW()
    WHERE id = NEW.table_id
      AND estado NOT IN ('bloqueada', 'reservada');

  ELSIF TG_OP = 'UPDATE' AND NEW.estado IN ('cerrada', 'cancelada')
    AND OLD.estado NOT IN ('cerrada', 'cancelada') THEN

    SELECT COUNT(*) INTO v_ordenes_activas
    FROM restaurant_orders
    WHERE table_id = NEW.table_id
      AND estado NOT IN ('cerrada', 'cancelada')
      AND id != NEW.id;

    IF v_ordenes_activas = 0 THEN
      UPDATE restaurant_tables
      SET estado = 'limpieza', updated_at = NOW()
      WHERE id = NEW.table_id
        AND estado = 'ocupada';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.sincronizar_estado_mesa() OWNER TO postgres;

